//! Offline corpus generator: `seeds/<target>.txt` -> `corpus/<target>/seed-NNN`.
//!
//! The generator is deterministic: it reads only the seed lists and the optional donor data
//! directory and never the clock, the network or the environment. Synthetic TZif and ELF
//! images are built in code so the corpus can be regenerated byte-for-byte.

use std::fs;
use std::path::{Path, PathBuf};

use raven_libc_fuzz_replay::TARGETS;

fn parse_escapes(line: &str) -> Vec<u8> {
    let bytes = line.as_bytes();
    let mut out = Vec::new();
    let mut index = 0usize;
    while index < bytes.len() {
        let byte = bytes.get(index).copied().unwrap_or(0);
        index = index.saturating_add(1);
        if byte != b'\\' {
            out.push(byte);
            continue;
        }
        let Some(escape) = bytes.get(index).copied() else {
            out.push(b'\\');
            break;
        };
        index = index.saturating_add(1);
        match escape {
            b'x' => {
                let high = bytes.get(index).copied().unwrap_or(b'0');
                let low = bytes.get(index.saturating_add(1)).copied().unwrap_or(b'0');
                if let (Some(high), Some(low)) = (hex(high), hex(low)) {
                    out.push(high.wrapping_shl(4) | low);
                    index = index.saturating_add(2);
                }
            }
            b'n' => out.push(b'\n'),
            b'r' => out.push(b'\r'),
            b't' => out.push(b'\t'),
            b'\\' => out.push(b'\\'),
            other => out.push(other),
        }
    }
    out
}

fn hex(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte.wrapping_sub(b'0')),
        b'a'..=b'f' => Some(byte.wrapping_sub(b'a').wrapping_add(10)),
        b'A'..=b'F' => Some(byte.wrapping_sub(b'A').wrapping_add(10)),
        _ => None,
    }
}

fn read_seeds(path: &Path) -> Result<Vec<Vec<u8>>, String> {
    let text = fs::read_to_string(path).map_err(|error| format!("{}: {error}", path.display()))?;
    let mut out = Vec::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        out.push(parse_escapes(trimmed));
    }
    Ok(out)
}

fn put16(out: &mut Vec<u8>, value: u16) {
    out.extend_from_slice(&value.to_le_bytes());
}
fn put32(out: &mut Vec<u8>, value: u32) {
    out.extend_from_slice(&value.to_le_bytes());
}
fn put64(out: &mut Vec<u8>, value: u64) {
    out.extend_from_slice(&value.to_le_bytes());
}
fn putbe32(out: &mut Vec<u8>, value: u32) {
    out.extend_from_slice(&value.to_be_bytes());
}

fn tzif_utc() -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"TZif");
    out.push(b'2');
    out.extend_from_slice(&[0u8; 15]);
    putbe32(&mut out, 0);
    putbe32(&mut out, 0);
    putbe32(&mut out, 1);
    putbe32(&mut out, 4);
    putbe32(&mut out, 0);
    putbe32(&mut out, 0);
    out.extend_from_slice(&[0, 0, 0, 0]);
    out.push(0);
    out.push(0);
    out.extend_from_slice(b"UTC\0");
    out.extend_from_slice(b"\n\n");
    out.extend_from_slice(b"UTC0");
    out.push(b'\n');
    out
}

fn tzif_two_transitions() -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"TZif");
    out.push(b'2');
    out.extend_from_slice(&[0u8; 15]);
    putbe32(&mut out, 0);
    putbe32(&mut out, 2);
    putbe32(&mut out, 2);
    putbe32(&mut out, 8);
    putbe32(&mut out, 0);
    putbe32(&mut out, 0);
    out.extend_from_slice(&0i32.to_be_bytes());
    out.extend_from_slice(&3600i32.to_be_bytes());
    out.extend_from_slice(&[0, 1]);
    out.extend_from_slice(&0i32.to_be_bytes());
    out.push(0);
    out.push(0);
    out.extend_from_slice(&3600i32.to_be_bytes());
    out.push(4);
    out.push(1);
    out.extend_from_slice(b"UTC\0CET\0");
    out.extend_from_slice(b"\n\n");
    out.extend_from_slice(b"UTC0\n");
    out
}

fn elf_image(truncate: Option<usize>) -> Vec<u8> {
    let ehdr_size = 64usize;
    let phdr_size = 56usize;
    let phnum = 2usize;
    let phoff = ehdr_size;
    let dyn_off = phoff + phnum * phdr_size;
    let hash_off = dyn_off + 16 * 8;
    let sym_off = hash_off + 8 * 4;
    let str_off = sym_off + 3 * 24;
    let rela_off = str_off + 12;
    let total = rela_off + 24;

    let mut out = Vec::with_capacity(total);
    out.extend_from_slice(&[0x7f, b'E', b'L', b'F', 2, 1, 1, 0]);
    out.extend_from_slice(&[0u8; 8]);
    put16(&mut out, 3);
    put16(&mut out, 62);
    put32(&mut out, 1);
    put64(&mut out, 0);
    put64(&mut out, phoff as u64);
    put64(&mut out, 0);
    put32(&mut out, 0);
    put16(&mut out, ehdr_size as u16);
    put16(&mut out, phdr_size as u16);
    put16(&mut out, phnum as u16);
    put16(&mut out, 0);
    put16(&mut out, 0);
    put16(&mut out, 0);

    // PT_LOAD: one writable, executable segment covering the image.
    put32(&mut out, 1);
    put32(&mut out, 7);
    put64(&mut out, 0);
    put64(&mut out, 0);
    put64(&mut out, 0);
    put64(&mut out, total as u64);
    put64(&mut out, total as u64);
    put64(&mut out, 0x1000);

    // PT_DYNAMIC.
    put32(&mut out, 2);
    put32(&mut out, 6);
    put64(&mut out, dyn_off as u64);
    put64(&mut out, dyn_off as u64);
    put64(&mut out, dyn_off as u64);
    put64(&mut out, (16 * 8) as u64);
    put64(&mut out, (16 * 8) as u64);
    put64(&mut out, 8);

    let dynamic = [
        (4u64, hash_off as u64),
        (5, sym_off as u64),
        (6, str_off as u64),
        (7, rela_off as u64),
        (8, 24),
        (9, 24),
        (10, 12),
        (11, 24),
        (0, 0),
    ];
    for (tag, value) in dynamic {
        put64(&mut out, tag);
        put64(&mut out, value);
    }
    while out.len() < hash_off {
        out.push(0);
    }
    put32(&mut out, 1);
    put32(&mut out, 3);
    put32(&mut out, 0);
    put32(&mut out, 0);
    put32(&mut out, 0);
    put32(&mut out, 0);
    put32(&mut out, 0);
    put32(&mut out, 0);

    // Symbol 0: null. Symbol 1: foo. Symbol 2: bar.
    out.extend_from_slice(&[0u8; 24]);
    put32(&mut out, 1);
    out.push(0x12);
    out.push(0);
    put16(&mut out, 1);
    put64(&mut out, 0);
    put64(&mut out, 0);
    put32(&mut out, 5);
    out.push(0x12);
    out.push(0);
    put16(&mut out, 1);
    put64(&mut out, 0);
    put64(&mut out, 0);
    out.extend_from_slice(b"\0foo\0bar\0");
    while out.len() < str_off + 12 {
        out.push(0);
    }
    // One R_X86_64_RELATIVE at offset 0.
    put64(&mut out, 0);
    put64(&mut out, 8);
    put64(&mut out, 0);
    while out.len() < total {
        out.push(0);
    }
    if let Some(limit) = truncate {
        out.truncate(limit.min(out.len()));
    }
    out
}

fn elf_seeds() -> Vec<Vec<u8>> {
    let base = elf_image(None);
    let mut out = vec![vec![0u8, 0], base.clone()];
    for (arch, bias) in [(0u8, 0u8), (1, 1), (2, 0)] {
        let mut seed = vec![arch, bias];
        seed.extend_from_slice(&base);
        seed.extend_from_slice(b"foo\0bar\0");
        out.push(seed);
    }
    for limit in [16usize, 32, 63, 64, 80, 128, 200, 300, 400, base.len() - 1] {
        let mut seed = vec![0u8, 0];
        seed.extend_from_slice(&elf_image(Some(limit)));
        out.push(seed);
    }
    for (index, mask) in [0x01u8, 0x80, 0xff].into_iter().enumerate() {
        let mut broken = base.clone();
        if let Some(slot) = broken.get_mut(40usize.saturating_add(index)) {
            *slot ^= mask;
        }
        let mut seed = vec![0u8, 0];
        seed.extend_from_slice(&broken);
        out.push(seed);
    }
    out
}

fn time_seeds() -> Vec<Vec<u8>> {
    fn seed(fields: [i32; 9], selector: u8, flags: u8, format: &[u8], subject: &[u8]) -> Vec<u8> {
        let mut out = Vec::new();
        for field in fields {
            out.extend_from_slice(&field.to_le_bytes());
        }
        out.push(selector);
        out.push(flags);
        out.extend_from_slice(format);
        out.push(0);
        out.extend_from_slice(subject);
        out
    }
    let normal = [56, 34, 12, 13, 10, 126, 5, 317, 0];
    let minimum = [i32::MIN; 9];
    let maximum = [i32::MAX; 9];
    vec![
        seed(normal, 0, 0, b"%Y-%m-%d %H:%M:%S", b"2026-11-13 12:34:56"),
        seed(normal, 1, 0, b"%Y-%m-%d %H:%M:%S", b"2026-11-13 12:34:56"),
        seed(normal, 2, 0, b"%Y-%m-%d %H:%M:%S", b"2026-11-13 12:34:56"),
        seed(normal, 0, 1, b"%c", b""),
        seed(normal, 0, 0, b"%", b""),
        seed(normal, 0, 0, b"%E", b""),
        seed(normal, 0, 0, b"%Ey", b""),
        seed(normal, 0, 0, b"%OS", b""),
        seed(normal, 0, 0, b"%-d %_5Y %^a %#Z", b""),
        seed(minimum, 0, 0, b"%c", b""),
        seed(maximum, 2, 1, b"%s %Z", b""),
        seed(
            [0, 0, 0, 1, 0, 70, 0, 0, 0],
            0,
            0,
            b"%Y-%m-%d",
            b"1970-01-01",
        ),
    ]
}

fn dns_seeds() -> Vec<Vec<u8>> {
    fn header(count: u16, answer: bool) -> Vec<u8> {
        let mut out = vec![0u8; 12];
        out[2] = if answer { 0x81 } else { 0x01 };
        out[4..6].copy_from_slice(&count.to_be_bytes());
        if answer {
            out[6..8].copy_from_slice(&1u16.to_be_bytes());
        }
        out
    }
    let mut query = header(1, false);
    query.extend_from_slice(&[
        3, b'w', b'w', b'w', 7, b'e', b'x', b'a', b'm', b'p', b'l', b'e', 0,
    ]);
    query.extend_from_slice(&[0, 1, 0, 1]);
    let mut answer = header(1, true);
    answer.extend_from_slice(&[
        3, b'w', b'w', b'w', 7, b'e', b'x', b'a', b'm', b'p', b'l', b'e', 0,
    ]);
    answer.extend_from_slice(&[0, 1, 0, 1]);
    answer.extend_from_slice(&[0xc0, 0x0c, 0, 1, 0, 1, 0, 0, 0, 60, 0, 4, 192, 0, 2, 1]);
    let mut compressed = header(1, false);
    compressed.extend_from_slice(&[0xc0, 0x0c]);
    let mut short = header(0, false);
    short.truncate(6);
    let mut self_pointer = header(1, false);
    self_pointer.extend_from_slice(&[0xc0, 0x0c]);
    let mut long_label = header(1, false);
    long_label.push(63);
    long_label.extend_from_slice(&[b'a'; 63]);
    long_label.push(0xc0);
    let mut many = header(1, false);
    many.extend_from_slice(&[3, b'a', b'b', b'c', 0, 0, 1, 0, 1]);
    vec![
        query,
        answer,
        compressed,
        short,
        self_pointer,
        long_label,
        many,
    ]
}

fn default_resources() -> PathBuf {
    let start = Path::new(env!("CARGO_MANIFEST_DIR"));
    for ancestor in start.ancestors() {
        let candidate = ancestor.join("ravenbsd-resources");
        if candidate.is_dir() {
            return candidate;
        }
    }
    start.join("ravenbsd-resources")
}

fn regex_donor_seeds(resources: &Path) -> Vec<Vec<u8>> {
    let path = resources.join("netbsd/tests/lib/libc/regex/data");
    let mut out = Vec::new();
    let Ok(entries) = fs::read_dir(&path) else {
        println!("SKIP: {} not found", path.display());
        return out;
    };
    let mut files: Vec<PathBuf> = entries.flatten().map(|entry| entry.path()).collect();
    files.sort();
    for file in files.iter().take(3) {
        let Ok(text) = fs::read_to_string(file) else {
            continue;
        };
        for line in text.lines().take(4) {
            let mut parts = line.split('\t');
            let pattern = parts.next().unwrap_or("");
            let subject = parts.next().unwrap_or("");
            if pattern.is_empty() {
                continue;
            }
            let length = u16::try_from(pattern.len()).unwrap_or(u16::MAX);
            let mut seed = vec![0u8, 0];
            seed.extend_from_slice(&length.to_le_bytes());
            seed.extend_from_slice(pattern.as_bytes());
            seed.extend_from_slice(subject.as_bytes());
            out.push(seed);
        }
    }
    out
}

fn write_corpus(out: &Path, name: &str, seeds: &[Vec<u8>]) -> Result<usize, String> {
    let directory = out.join(name);
    fs::create_dir_all(&directory).map_err(|error| format!("{}: {error}", directory.display()))?;
    for entry in fs::read_dir(&directory)
        .map_err(|error| format!("{}: {error}", directory.display()))?
        .flatten()
    {
        let path = entry.path();
        if path.is_file() {
            fs::remove_file(&path).map_err(|error| format!("{}: {error}", path.display()))?;
        }
    }
    fs::write(directory.join("seed-000"), []).map_err(|error| error.to_string())?;
    for (index, seed) in seeds.iter().take(299).enumerate() {
        let path = directory.join(format!("seed-{:03}", index.saturating_add(1)));
        let limited = seed.get(..1024).unwrap_or(seed);
        fs::write(&path, limited).map_err(|error| format!("{}: {error}", path.display()))?;
    }
    Ok(seeds.len().min(299).saturating_add(1))
}

fn main() {
    let mut out = PathBuf::from("tests/libc/fuzz/corpus");
    let mut seeds_dir = PathBuf::from("tests/libc/fuzz/seeds");
    let mut resources = default_resources();
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--out" => out = PathBuf::from(args.next().unwrap_or_default()),
            "--seeds" => seeds_dir = PathBuf::from(args.next().unwrap_or_default()),
            "--resources" => resources = PathBuf::from(args.next().unwrap_or_default()),
            other => {
                eprintln!("seedgen: unknown argument {other}");
                std::process::exit(2);
            }
        }
    }
    fs::create_dir_all(&out).expect("create corpus");
    let mut failures = 0usize;
    for (name, _) in TARGETS {
        let path = seeds_dir.join(format!("{name}.txt"));
        let mut seeds = match read_seeds(&path) {
            Ok(seeds) => seeds,
            Err(error) => {
                eprintln!("seedgen: {error}");
                failures = failures.saturating_add(1);
                Vec::new()
            }
        };
        if *name == "printf_format" || *name == "scanf_format" {
            seeds = seeds
                .into_iter()
                .map(|seed| {
                    let mut padded = Vec::with_capacity(seed.len().saturating_add(384));
                    padded.push(seed.first().copied().unwrap_or(0));
                    padded.extend_from_slice(&[0u8; 384]);
                    padded.extend_from_slice(seed.get(1..).unwrap_or(&[]));
                    padded
                })
                .collect();
        }
        match *name {
            "tz_parse" => {
                seeds.push(tzif_utc());
                seeds.push(tzif_two_transitions());
                let base = tzif_two_transitions();
                for limit in [4usize, 8, 16, 32, base.len() - 1] {
                    seeds.push(base.get(..limit).unwrap_or(&base).to_vec());
                }
            }
            "elf_dynamic" => seeds.extend(elf_seeds()),
            "time_format" => seeds.extend(time_seeds()),
            "resolver_message" => seeds.extend(dns_seeds()),
            "regex_compile_exec" => seeds.extend(regex_donor_seeds(&resources)),
            _ => {}
        }
        match write_corpus(&out, name, &seeds) {
            Ok(count) if count >= 10 => println!("{name}: {count} seeds"),
            Ok(count) => {
                eprintln!("seedgen: {name} has only {count} seeds");
                failures = failures.saturating_add(1);
            }
            Err(error) => {
                eprintln!("seedgen: {error}");
                failures = failures.saturating_add(1);
            }
        }
    }
    if failures != 0 {
        std::process::exit(1);
    }
}
